// Where the app looks for update info. version.json is generated by scripts/release-update.sh and
// committed to the main branch of the mobile repo. Override at build time with NEXT_PUBLIC_UPDATE_MANIFEST_URL.
export const UPDATE_MANIFEST_URL =
  process.env.NEXT_PUBLIC_UPDATE_MANIFEST_URL ??
  "https://raw.githubusercontent.com/dBillionaire-Dev/Clinexia_V3.0-Mobile/main/version.json"

export const LAST_CHECK_KEY = "clinexia:update:last-check"
export const UPDATE_EVENT = "clinexia:update-available"
